body.raw:
{
  "name": "{{name}}",
  "allowed_origins": [
    "{{allowed_origins}}"
  ],
  "allowed_capabilities": [
    "{{allowed_capabilities}}"
  ],
  "rate_limit_per_minute": 1.0,
  "session_ttl_seconds": 60.0,
  "require_published_agent": true,
  "widget_config": {
    "title": "Talk with our AI Assistant",
    "subtitle": "Ask a question or start a live voice session",
    "greeting": "Hello! How can I help you today?",
    "placeholder": "Type your message...",
    "primary_color": "#2563eb",
    "position": "bottom-right",
    "enable_chat": true,
    "enable_voice": true,
    "show_branding": true,
    "captcha": {
      "enabled": true,
      "provider": "recaptcha_v3",
      "threshold": 0.5,
      "site_key": ""
    },
    "budget": {
      "daily_requests": 500,
      "daily_seconds": 3600
    }
  }
}
